return ['domain'=>'zinn-offload','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'hr','project-id-version'=>'zinn-offload','pot-creation-date'=>'2026-09-06T10:05:56+00:00','po-revision-date'=>'2026-09-06T10:05:56+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Media Offload'=>'Zinn® Media Offload','https://zinndigital.com/wordpress-plugins/zinn-offload'=>'https://zinndigital.com/wordpress-plugins/zinn-offload','Moves this site\'s media library to Zinn® object storage and serves it from a CDN. Configured from your Zinn® dashboard — no access key is ever typed into WordPress.'=>'Premješta medijsku biblioteku ove web-lokacije u Zinn® objektnu pohranu i poslužuje je s CDN-a. Konfigurira se s vaše Zinn® upravljačke ploče — u WordPress se nikada ne upisuje pristupni ključ.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Zinn Digital® did not return a token. Nothing has been changed on this site.'=>'Zinn Digital® nije vratio token. Na ovoj stranici ništa nije promijenjeno.','That file could not be read from this server, so nothing was uploaded.'=>'Tu datoteku nije bilo moguće pročitati s ovog poslužitelja, pa ništa nije učitano.','Storage refused the upload (HTTP %d). The file is still on this server.'=>'Pohrana je odbila prijenos (HTTP %d). Datoteka je još uvijek na ovom poslužitelju.','This site is no longer connected to Zinn® media offload. New uploads will stay on this server. Pair it again from your Zinn Digital® dashboard.'=>'Ova stranica više nije povezana s prijenosom medija na Zinn®. Novi prijenos ostat će na ovom poslužitelju. Ponovno ju povežite sa svoje nadzorne ploče za Zinn Digital®.','Zinn Digital® answered with HTTP %d.'=>'Zinn Digital® je odgovorio s HTTP %d.','Disconnected by Zinn Digital®.'=>'Prekinuta veza od strane Zinn Digital®-a.','%s — guides and services'=>'%s — vodiči i usluge','User guides'=>'Korisnički priručnici','Read the %s user guide'=>'Pročitajte korisnički priručnik za %s','Hide this'=>'Sakrij ovo','Zinn® hosting for WordPress'=>'Zinn® hosting za WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, dnevne sigurnosne kopije, besplatna migracija i upravljačka ploča prilagođena korisnicima koji vode više web-mjesta.','The Zinn® marketplace'=>'Zinn® tržnica','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte i prodajte već uspostavljene stranice, domene i postavljanja poveznica, uz sigurno čuvanje novca dok obje strane ne budu zadovoljne.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — zaposlite stručnjake koji se time bave','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Naše globalno tržište slobodnih zanimanja: pregledajte više od 10.000 gotovih usluga pisaca, dizajnera, programera i SEO stručnjaka ili objavite projekt i dopustite im da daju ponude.','You do not have permission to manage this site.'=>'Nemate dopuštenje za upravljanje ovom stranicom.','Open your Zinn Digital® dashboard, turn on media offload for this site, and paste the pairing code it shows you. No access key is needed — this site never holds one.'=>'Otvorite svoju nadzornu ploču Zinn Digital®, uključite prijenos medija za ovu web-lokaciju i zalijepite kod za uparivanje koji vam se prikaže. Ključ za pristup nije potreban – ova web-lokacija ga nikada ne posjeduje.','Pairing code'=>'Kod za uparivanje','Connect this site'=>'Povežite ovu web-lokaciju','Status'=>'Status','Connected to your Zinn Digital® account'=>'Povezano s vašim Zinn Digital® računom','Media served from'=>'Medij poslužen s','This server (offloaded copies are being kept, but not served yet)'=>'Ovaj poslužitelj (izmještene kopije se pohranjuju, ali se još ne poslužuju)','Local copies'=>'Lokalne kopije','Removed once every size has uploaded'=>'Uklonjeno nakon što se svaka veličina učita','Kept on this server'=>'Zadržano na ovom poslužitelju','Offloaded so far'=>'Dosad preneseno','%1$s files, %2$s'=>'%1$s datoteka, %2$s','Still on this server'=>'Još uvijek na ovom poslužitelju','%1$s of %2$s attachments'=>'%1$s od %2$s privitaka','Older media moves in the background, a few files an hour, and picks up where it left off. Nothing is deleted from this server unless your dashboard says so.'=>'Stariji mediji se prenose u pozadini, nekoliko datoteka na sat, i nastavljaju tamo gdje su stali. Ništa se ne briše s ovog poslužitelja osim ako vaša upravljačka ploča tako ne nalaže.','Last problem'=>'Posljednji problem','Disconnect this site'=>'Odspoji ovu stranicu','New uploads will stay on this server. Media already moved keeps working — its address does not change.'=>'Nova prenesena datoteka ostat će na ovom poslužitelju. Već premješteni medijski sadržaji nastavljaju raditi — njihova adresa se ne mijenja.','Paste the pairing code from your Zinn Digital® dashboard.'=>'Zalijepite kod za uparivanje s vaše nadzorne ploče za Zinn Digital®.','Connected. New uploads will be stored with Zinn Digital® from now on, and your existing media will move in the background.'=>'Povezano. Novi prijenosi od sada će se pohranjivati na Zinn Digital®, a vaši postojeći mediji premjestit će se u pozadini.','Disconnected. Media already moved keeps working; new uploads stay on this server.'=>'Prekinuta veza. Mediji koji su već premješteni nastavljaju raditi; novi prijenosi ostaju na ovom poslužitelju.','See the Zinn Digital® release notes.'=>'Pogledajte bilješke o izdanju Zinn Digital®.','The downloaded update failed its integrity check and was not installed.'=>'Preuzeto ažuriranje nije prošlo provjeru integriteta i nije instalirano.']];